import {absolute,crewAvailable,crewName} from './crew.js?v=09c';
export const TRACE_CASES=[
 {site:'engineering',other:'canteen',ownerId:'P02',domain:'water',at:620,title:'兩份用水紀錄對不上',notice:'工程與餐廳的用水回報有落差，各區先維持原本的安全安排。請留意現場與不同來源的紀錄。',clues:{engineering:'支路壓力在短時間內反覆變動；主供水讀值正常，換濾網的舊紀錄不能代表現在。',canteen:'餐廳今天用了較多備水，但領用人數沒有增加；後勤保留了領用單。'},fix:'工程師逐段對照支路閥位與壓力，調整後再觀察；餐廳的備水領用另留紀錄。'},
 {site:'power',other:'engineering',ownerId:'P02',domain:'power',at:640,title:'備援測試與末端讀值不同',notice:'供電總表與一份設備測試單的時間接近，讀值卻不同。必要設備仍有供電，各區先保留原始數據。',clues:{power:'一組備援在測試負載下讀值波動，主供電平穩；接頭需要工程依程序複查。',engineering:'末端自檢有短暫重啟，設備本體的檢查沒有重現；時間與備援測試重疊。'},fix:'工程師停用該組測試負載並複查接頭，再以替代備援交叉測試；主供電維持正常。'},
 {site:'supplies',other:'medical',ownerId:'P04',domain:'food',at:650,title:'可領數量與封存紀錄有差異',notice:'兩份物資紀錄的數量對不上，後勤先分開保管，沒有把待查物品發出。請從來源比對。',clues:{supplies:'同一批箱子貼了兩個庫位標籤，系統可領欄有重複計入的跡象。',medical:'醫護只收到一批封存用品，領用與保存紀錄沒有第二批；目前沒有品質判定。'},fix:'後勤逐箱對批次與庫位，移除重複的可領登錄並留下更正紀錄；沒有推定物品變質。'}
];
function add(s,id,type,actor,text,at=s.time,day=s.day||1){const e=s.events.find(e=>e.id===id);e.entries.push({id:id+'-'+(e.entries.length+1),day,time:at,type,actor,text});}
export function investigationOf(s){return (s.investigations||[]).find(q=>q.status==='比對中'||q.status==='複查中')||(s.investigations||[]).at(-1)||null;}
export function processInvestigation(s){
 s.investigations=s.investigations||[];
 const work=s.traceWork;if(work&&absolute(s)>=work.due){const d=TRACE_CASES[work.caseDay-1],q=s.investigations.find(q=>q.id===work.id),e=s.events.find(e=>e.id===work.id),at=work.due%1440,day=Math.floor(work.due/1440)+1;if(q&&e){e.status='已結案';e.closed=at;e.closedDay=day;add(s,e.id,'完成回報',crewName(work.ownerId),d.fix,at,day);q.status='已完成';s.health=Math.min(100,s.health+1);s.trust=Math.min(100,s.trust+2);if(s.world)s.world.resources[d.domain]=Math.min(100,s.world.resources[d.domain]+2);s.last=crewName(work.ownerId)+'已完成複查，原始紀錄與更正都已保留。';}s.traceWork=null;}
 const d=TRACE_CASES[(s.day||1)-1];if(!d||!s.signed||s.ended||s.time<d.at||s.investigations.some(q=>q.day===s.day))return;
 const id=`EV-212609${15+s.day}-CHECK`;s.investigations.push({id,day:s.day,site:d.site,other:d.other,status:'比對中',clues:[],attempts:[]});s.events.push({id,title:d.title,category:'巡查對照',opened:d.at,openedDay:s.day,status:'比對中',owner:crewName(d.ownerId),closed:null,entries:[],attachments:[]});add(s,id,'來源差異','值班紀錄',d.notice,d.at);
}
export function inspectArea(s){const q=investigationOf(s),d=TRACE_CASES[(q?.day||1)-1];if(!q||q.status!=='比對中')return '目前沒有新的紀錄差異要比對。';if(q.clues.some(x=>x.location===s.location))return '這個位置的觀察已經記下，請找其他來源對照。';const text=d.clues[s.location]||'當班紀錄與現場的可見指示目前一致，沒有足夠證據把這裡當作來源。';q.clues.push({location:s.location,text,time:s.time,day:s.day});add(s,q.id,'現場觀察','玩家',text);s.last='這裡的觀察已記下。再找不同來源比對，不靠一張畫面下結論。';return null;}
export function diagnoseArea(s,site){const q=investigationOf(s),d=TRACE_CASES[(q?.day||1)-1];if(!q||q.status!=='比對中')return '目前沒有待比對的新項目。';if(q.clues.length<2)return '先取得至少兩處的觀察，再提出複查位置。';if(q.attempts.some(a=>a.site===site&&a.count>=q.clues.length))return '這個位置已提過；先補上新的觀察再回報。';q.attempts.push({site,count:q.clues.length});if(site!==d.site||!q.clues.some(x=>x.location===d.site)||!q.clues.some(x=>x.location===d.other)){add(s,q.id,'判讀待補','玩家','提出複查位置，但現有來源不足以支持。原安全安排保持，繼續收集對照。');s.last='這個位置或證據還不足。同事維持原安全安排，請再對照不同來源。';return null;}
 const start=crewAvailable(s,d.ownerId,q.id),due=start+12;q.status='複查中';s.traceWork={id:q.id,ownerId:d.ownerId,caseDay:q.day,start,due};const e=s.events.find(e=>e.id===q.id);e.status='處理中';add(s,q.id,'玩家判讀','玩家','兩份來源已對照，指出需要複查的工作位置。');add(s,q.id,'接手確認',crewName(d.ownerId),'已接下複查，先完成手上的工作再處理，預計9/'+(16+Math.floor(due/1440))+' '+String(Math.floor(due%1440/60)).padStart(2,'0')+':'+String(due%60).padStart(2,'0')+' 回報。');s.last='複查已交給負責人。你指出了方向，不代表機器已經修好。';return null;}
